// CAN CHINH SUA O DAY
const config = {
  team_id: "9018351620",
  space_id: "90183192291", // XAC NHAN DUNG tu du lieu ClickUp that (task.space.id). Loi "Space ID invalid" truoc do la do Config bi sai format number/string, khong phai sai ID.

  // De trong = lay tu gateway.config (admin_chat_id). Dien vao = ghi de, vi du gui
  // sang 1 group Telegram rieng thay vi nhan admin ca nhan.
  notifyChatId: "",

  // BAT/TAT che do test: gioi han nho de chay nhanh, khong can lay het DB
  testMode: true,
  testFolderLimit: 2,   // chi lay N folder dau (ke ca "folderless lists" tinh la 1 nhom)
  testTaskLimit: 5,     // chi lay N task dau moi List

  // Co lay comment de trich link OneDrive/Youtube trong lan full sync khong.
  // Day la phan ton API nhieu nhat (1 call/task). Tat neu chi muon test nhanh cot co ban.
  fetchCommentsInFullSync: true,

  // Map ten cot Postgres -> TEN custom field trong ClickUp (khong phai ID).
  // CAP NHAT theo du lieu THAT tu ClickUp (khong con la phong doan):
  fieldNameMap: {
    b1_datum:          "B1 Datum",              // type: date
    dob:               "DOB",                    // type: date
    ma_hd:             "Mã HĐ",                  // type: short_text
    nghe:              "Nghề",                   // type: text
    sdt:               "SDT",                    // type: phone
    email:             "email",                  // type: email
    dia_chi_vn:        "Địa chỉ VN",              // type: short_text
    vfs:               "🌍 VFS",                  // type: date - CO EMOJI, giu nguyen
    du_kien_den_duc:   "📆 Dự kiến thời gian đến Đức", // type: date
    ngay_xuat_canh:    "🛫 Ngày xuất cảnh",        // type: date
    dkpv_2026:         "DKPV 2026",               // type: list_relationship (link toi list Đơn Hàng)
    pvtc_2026:         "PVTC 2026",               // type: list_relationship
    nha_cua_support:   "Nhà cửa / Support",       // type: list_relationship
  }
};

return [{ json: config }];

const cfg = $('⚙️ Config').first().json;
const adminChatId = $json.admin_chat_id;
const chatId = cfg.notifyChatId || adminChatId;
const now = new Date();
const text = `🚀 <b>Bắt đầu đồng bộ ClickUp → Postgres (Full Reconcile)</b>\n` +
  `🕒 Thời gian bắt đầu: ${now.toLocaleString('vi-VN')}\n` +
  `${cfg.testMode ? '⚠️ Đang chạy TEST MODE (giới hạn dữ liệu)' : '📦 Chạy đầy đủ toàn bộ dữ liệu'}`;
return [{ json: { chatId, text, startTime: now.toISOString() } }];

// Merge node dam bao ca 2 nhanh (Get Folders + Get Folderless Lists) da chay xong
// truoc khi toi day, nen doc lai qua $('TenNode').all() la an toan (khong bi rung).
const cfg = $('⚙️ Config').first().json;
const folderItems = $('ClickUp - Get Folders').all().map(i => i.json);
const folderlessItems = $('ClickUp - Get Folderless Lists').all().map(i => i.json);

let allLists = [];
for (const folder of folderItems) {
  const listsInFolder = folder.lists || [];
  for (const l of listsInFolder) {
    allLists.push({ listId: String(l.id), listName: l.name, folderName: folder.name || '' });
  }
}
for (const l of folderlessItems) {
  allLists.push({ listId: String(l.id), listName: l.name, folderName: '' });
}

const seen = new Set();
allLists = allLists.filter(l => {
  if (seen.has(l.listId)) return false;
  seen.add(l.listId); return true;
});

if (cfg.testMode) {
  allLists = allLists.slice(0, cfg.testFolderLimit);
}

return allLists.map(l => ({ json: l }));

// Ghi thong ke tich luy qua workflow static data (khong mat khi qua nhieu vong lap)
const staticData = $getWorkflowStaticData('global');
if (!staticData.syncStats) {
  staticData.syncStats = { lists: [], totalTasks: 0, startedAt: new Date().toISOString() };
}
const currentList = $('Loop Over Lists').first().json;
const upsertedCount = $input.all().length;

let entry = staticData.syncStats.lists.find(l => l.listId === currentList.listId);
if (!entry) {
  entry = { listId: currentList.listId, listName: currentList.listName, taskCount: 0 };
  staticData.syncStats.lists.push(entry);
}
entry.taskCount += upsertedCount;
staticData.syncStats.totalTasks += upsertedCount;

return [{ json: { ok: true, listName: currentList.listName, upsertedCount } }];

const cfg = $('⚙️ Config').first().json;
const staticData = $getWorkflowStaticData('global');
const stats = staticData.syncStats || { lists: [], totalTasks: 0, startedAt: null };
const admin = $('Lay Admin Chat ID').first().json;
const chatId = cfg.notifyChatId || admin.admin_chat_id;
const now = new Date();
const durationSec = stats.startedAt ? Math.round((now - new Date(stats.startedAt)) / 1000) : null;

const listLines = stats.lists.map(l => `  • ${l.listName}: ${l.taskCount} task`).join('\n');
const text = `✅ <b>Đồng bộ ClickUp → Postgres HOÀN TẤT</b>\n\n` +
  `📋 Các List đã đồng bộ:\n${listLines || '  (không có)'}\n\n` +
  `📊 Tổng số task: <b>${stats.totalTasks}</b>\n` +
  `🕒 Kết thúc lúc: ${now.toLocaleString('vi-VN')}\n` +
  (durationSec !== null ? `⏱️ Thời gian chạy: ${durationSec}s\n` : '') +
  `#full_reconcile_done`;

delete staticData.syncStats;
return [{ json: { chatId, text } }];

// itemMatching(idx) tra dung task GOC ung voi comment o vi tri idx nho co che pairedItem cua n8n
const items = $input.all();
return items.map((it, idx) => {
  const parentTask = $('ClickUp - Get Tasks').itemMatching(idx).json;
  return { json: { ...it.json, taskId: parentTask.id } };
});

// Gom nhieu comment/task thanh 1 nhom, dong thoi TRICH LUON link OneDrive/Youtube
// (doc ca comment[].attributes.link va regex tren comment_text)
const items = $input.all();

const URL_RE = /https?:\/\/[^\s)"'\]]+/g;
function classifyLink(url) {
  const u = url.toLowerCase();
  if (u.includes('onedrive.live.com') || u.includes('1drv.ms') || u.includes('sharepoint.com')) return 'onedrive';
  if (u.includes('youtube.com') || u.includes('youtu.be')) return 'youtube';
  return null;
}

const grouped = {};
for (const it of items) {
  const c = it.json;
  const tid = c.taskId;
  if (!grouped[tid]) grouped[tid] = { onedriveLink: null, youtubeLink: null };
  const g = grouped[tid];

  const segs = Array.isArray(c.comment) ? c.comment : [];
  for (const seg of segs) {
    const link = seg.attributes && seg.attributes.link;
    if (link) {
      const kind = classifyLink(link);
      if (kind === 'onedrive' && !g.onedriveLink) g.onedriveLink = link;
      if (kind === 'youtube' && !g.youtubeLink) g.youtubeLink = link;
    }
  }
  const plain = c.comment_text || '';
  const matches = plain.match(URL_RE) || [];
  for (const url of matches) {
    const kind = classifyLink(url);
    if (kind === 'onedrive' && !g.onedriveLink) g.onedriveLink = url;
    if (kind === 'youtube' && !g.youtubeLink) g.youtubeLink = url;
  }
}

const entries = Object.entries(grouped);
if (entries.length === 0) {
  // Dam bao luon co it nhat 1 item de node phia sau (Ghep Task + Comment) khong bi bo qua
  return [{ json: { taskId: '__no_comments__', onedriveLink: null, youtubeLink: null } }];
}
return entries.map(([taskId, g]) => ({
  json: { taskId, onedriveLink: g.onedriveLink, youtubeLink: g.youtubeLink }
}));

// Doc lai TOAN BO task tu 'Limit (test mode)' (khong phai tu nhanh comment) de KHONG mat task
// nao khong co comment. Node nay chay SAU 'Group Comments theo Task' nen Get Tasks/Limit chac
// chan da chay xong -> $('...').all() an toan, khong bi rung thu tu.
const cfg = $('⚙️ Config').first().json;
const currentList = $('Loop Over Lists').first().json; // { listId, listName, folderName }
const allTasks = $('Limit (test mode)').all().map(i => i.json);
const commentGroups = $input.all().map(i => i.json); // [{ taskId, onedriveLink, youtubeLink }]
const commentByTaskId = new Map(commentGroups.map(g => [String(g.taskId), g]));

const fieldNameMap = cfg.fieldNameMap;

const normalize = (s) => (s || '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/\u0111/g, 'd').replace(/\u0110/g, 'D').toLowerCase();

function getCF(customFields, name) {
  if (!Array.isArray(customFields) || !name) return null;
  const f = customFields.find(cf => (cf.name || '').trim().toLowerCase() === name.trim().toLowerCase());
  if (!f || f.value === undefined || f.value === null) return null;

  // list_relationship: value la mang object {name, status, url...} - lay ten (+ status)
  if (f.type === 'list_relationship' && Array.isArray(f.value)) {
    return f.value.map(v => v.status ? `${v.name} (${v.status})` : v.name).join('; ');
  }
  // date: value la epoch ms dang string -> format dd/mm/yyyy
  if (f.type === 'date' || /^\d{10,13}$/.test(String(f.value))) {
    const d = new Date(Number(f.value));
    if (!isNaN(d.getTime())) {
      const dd = String(d.getDate()).padStart(2, '0');
      const mm = String(d.getMonth() + 1).padStart(2, '0');
      return `${dd}/${mm}/${d.getFullYear()}`;
    }
  }
  if (typeof f.value === 'object') return JSON.stringify(f.value);
  return String(f.value);
}

return allTasks.map(t => {
  const cfs = t.custom_fields || [];
  const commentGroup = commentByTaskId.get(String(t.id));

  let phuTrach = '';
  if (Array.isArray(t.assignees) && t.assignees.length > 0) {
    phuTrach = t.assignees.map(a => a.username || a.email).filter(Boolean).join(', ');
  }

  return {
    json: {
      id: t.id,
      name: t.name || '',
      name_khong_dau: normalize(t.name || ''),
      url: t.url || '',
      description: t.text_content || t.description || '',
      status: t.status?.status || '',
      team_id: t.team_id || cfg.team_id,
      space_id: t.space?.id || cfg.space_id,
      folder_id: t.folder?.id || '',
      folder_name: t.folder?.name || currentList.folderName || '',
      list_id: t.list?.id || currentList.listId || '',
      list_name: t.list?.name || currentList.listName || '',
      phu_trach: phuTrach,
      b1_datum: getCF(cfs, fieldNameMap.b1_datum) || '',
      dob: getCF(cfs, fieldNameMap.dob) || '',
      ma_hd: getCF(cfs, fieldNameMap.ma_hd) || '',
      nghe: getCF(cfs, fieldNameMap.nghe) || '',
      sdt: getCF(cfs, fieldNameMap.sdt) || '',
      email: getCF(cfs, fieldNameMap.email) || '',
      dia_chi_vn: getCF(cfs, fieldNameMap.dia_chi_vn) || '',
      vfs: getCF(cfs, fieldNameMap.vfs) || '',
      du_kien_den_duc: getCF(cfs, fieldNameMap.du_kien_den_duc) || '',
      ngay_xuat_canh: getCF(cfs, fieldNameMap.ngay_xuat_canh) || '',
      dkpv_2026: getCF(cfs, fieldNameMap.dkpv_2026) || '',
      pvtc_2026: getCF(cfs, fieldNameMap.pvtc_2026) || '',
      nha_cua_support: getCF(cfs, fieldNameMap.nha_cua_support) || '',
      onedrive_link: commentGroup?.onedriveLink || '',
      youtube_link: commentGroup?.youtubeLink || '',
      date_updated: t.date_updated ? new Date(Number(t.date_updated)).toISOString() : null,
    }
  };
});
